export function viewportSize(win){const visual=win.visualViewport,useVisual=visual&&Math.abs((visual.scale||1)-1)<.01;const width=Math.max(1,Math.round(useVisual?visual.width:win.innerWidth)),height=Math.max(1,Math.round(useVisual?visual.height:win.innerHeight));return {width,height,pixelRatio:Math.min(1.65,Math.max(1,Number(win.devicePixelRatio)||1))};}
export function watchViewport(win,apply){let pending=false;const update=()=>{pending=false;const size=viewportSize(win);const style=win.document.documentElement.style;style.setProperty('--app-width',size.width+'px');style.setProperty('--app-height',size.height+'px');apply(size);};const schedule=()=>{if(!pending){pending=true;win.requestAnimationFrame(update);}};for(const event of ['resize','orientationchange','pageshow'])win.addEventListener(event,schedule);win.visualViewport?.addEventListener('resize',schedule);win.visualViewport?.addEventListener('scroll',schedule);update();return schedule;}
